; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "text.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; The picture of figure 21.1 in this mode. The registers first, with the
; display off; then the whole VRAM filled with noise; then the mode's tables,
; and nothing else; then the display on.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $90          ; 16 KB, M1: text mode, display off
        VDP_REG 0, $00          ; mode: M3 = 0
        VDP_REG 2, $00          ; names    $0000
        VDP_REG 3, $00          ; no colour table in text mode
        VDP_REG 4, $01          ; patterns $0800
        VDP_REG 5, $00          ; no sprites in text mode
        VDP_REG 6, $00          ; no sprites in text mode
        VDP_REG 7, $1F          ; ink black (1), backdrop white (15)
        VRAM_WRITE $0000        ; every byte of the VRAM: noise, the
        ld hl, $0000            ; BIOS's first 16 KB
        ld c, VDP_DATA
        ld d, 64                ; 64 x 256 bytes
noise:  ld b, 0
        otir
        dec d
        jr nz, noise
        VRAM_WRITE $0800        ; the BIOS's 256 characters, 2,048 bytes
        ld hl, (CGTABL)
        ld c, VDP_DATA
        ld d, 8
font:   ld b, 0
        otir
        dec d
        jr nz, font
        ld hl, blocks           ; the tables gen21.py worked out
        call write_blocks
shown:  VDP_REG 1, $D0          ; the display on
done:   jr done

; write_blocks: HL = a list of blocks, each the VRAM address (2 bytes) and the
; number of bytes (2 bytes, 0 ends the list), then the bytes. Display off.
write_blocks:
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld c, (hl)
        inc hl
        ld b, (hl)
        inc hl
        ld a, b
        or c
        ret z
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
.byte:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .byte
        jr write_blocks
